import json
d=json.load(open('scene-contract.json'))
def walk(o,p='',d0=0):
    if d0>2: return
    if isinstance(o,dict):
        for k,v in o.items():
            print(p+'/'+k, type(v).__name__, (len(v) if isinstance(v,(list,dict,str)) else v))
            walk(v,p+'/'+k,d0+1)
    elif isinstance(o,list) and o and d0<2:
        walk(o[0],p+'[0]',d0+1)
walk(d)
" | head -120

python3 -c "
import json;d=json.load(open('scene-contract.json'))
for e in d['story']['events']: print(json.dumps(e))
"

