python3 -c "
import json;d=json.load(open('scene-contract.json'))
for o in d['guidance']['objectives']:
  print('---',o['id'],'|',o.get('agencyWindowRef'),'|kind=',o.get('kind'),'|enter=',o.get('enterAnchorRef'),'|clear=',o.get('clearAnchorRef'),'|marker=',o.get('requiresMarker'),repr(o.get('markerLabel')))
  print('  WO:',json.dumps(o.get('workOrder')))
  print('  target:',json.dumps(o.get('target') or o.get('markerTarget') or {}))
  print('  fb:',json.dumps(o.get('feedback')))
  for k in o:
    if k not in ('id','agencyWindowRef','kind','enterAnchorRef','clearAnchorRef','requiresMarker','markerLabel','workOrder','feedback','variantRefs','variantIntent','resetRef','resetTriggers','resetIntent','target','markerTarget'):
      print('  ',k,':',json.dumps(o[k])[:600])
"

