import type * as THREE from 'three';
import type { StoryBeat } from '../storyState.ts';

export interface MarkerPose {
  position: THREE.Vector3;
  surfaceUp?: THREE.Vector3 | null;
  projectionSpace?: 'surface' | 'spatial';
}
export type WorldMarkerHandle = 'anomaly' | 'summit' | 'pod' | 'waypoint' | 'tree'
  | 'origin-relay' | 'fire' | 'pond-surface' | 'pond-shore' | 'forage' | 'relay' | 'maw-pack' | 'keel'
  | 'wreck' | 'workstation' | 'hatch' | 'origin' | 'tidegarden' | 'station' | 'core' | 'fabricator';

/** The resolver knows positions and candidate facts, never React components. */
export interface WorldHandles {
  target(name: WorldMarkerHandle): MarkerPose | null;
  gather(resource: 'flint' | 'current'): MarkerPose | null;
  audit(beat: StoryBeat): MarkerPose | null;
  settlement(guidanceId: string): MarkerPose | null;
}
import type { StoryBeat } from '../storyState.ts';
import type { GuidedStoryObjective } from '../ux/objectiveDirector.ts';
import type { WorldHandles, MarkerPose } from './worldHandles.ts';
import { BEAT_DEFINITIONS } from './definitions.ts';
import { storyWorldHandles } from '../storyWorldHandles.ts';

let mountedWorldHandles: WorldHandles | null = null;

/** Bind the live scene once; all chapter publishers share this readiness boundary. */
export function registerStoryMarkerWorld(handles: WorldHandles | null): () => void {
  mountedWorldHandles = handles;
  return () => { if (mountedWorldHandles === handles) mountedWorldHandles = null; };
}

export function isStoryMarkerWorldMounted(): boolean { return mountedWorldHandles !== null; }

export interface StoryMarkerTarget extends MarkerPose { label: string }

/** Publication and rendering resolve the same candidate through the same beat contract. */
export function resolveMarkerTarget(
  beat: StoryBeat | null,
  candidate: Readonly<GuidedStoryObjective> | null,
  handles: WorldHandles = mountedWorldHandles ?? storyWorldHandles
): StoryMarkerTarget | null {
  if (!beat || !candidate || candidate.requiresMarker === false) return null;
  const target = BEAT_DEFINITIONS[beat]?.marker?.(handles, candidate);
  return target ? { ...target, label: candidate.markerLabel } : null;
}
import type { StoryBeat } from '../storyState.ts';
import type { RailRuntime } from '../autopilot.ts';
import { BEAT_DEFINITIONS } from '../beats/definitions.ts';

export const BEAT_RAILS: Partial<Record<StoryBeat, (ctx: RailRuntime) => void>> = Object.fromEntries(
  Object.values(BEAT_DEFINITIONS).filter(beat => beat.rail.tick).map(beat => [beat.id, beat.rail.tick])
);
import { registerBeat } from '../registry.ts';
import { beatCh10Cold } from './ch10-cold.ts';
import { beatCh10Ask } from './ch10-ask.ts';
import { beatCh10Transit } from './ch10-transit.ts';

export const CH10_BEATS = [beatCh10Cold, beatCh10Ask, beatCh10Transit] as const;
for (const contract of CH10_BEATS) registerBeat(contract);
import { defineBeat } from '../beatContract.ts';
import * as input from '../inputPrimitives.ts';
import { ch10TransitObjective } from '../objectivePrimitives.ts';
import { tick } from './rail-ch10-transit.ts';

/** The authored behaviour and journey declaration for ch10-transit. */
export const beatCh10Transit = defineBeat({
  id: "ch10-transit",
  chapter: "ch10",
  disposition: "objective",
  entry: "sequence",
  objective: facts => ch10TransitObjective(facts.ch10TransitState),
  input: { ...input.SANDBOX_POLICY },
  hud: {
  "feedEffects": false,
  "embodiedGuidance": true,
  "earlyTouchDpad": false,
  "externalCamera": false
},
  rail: { stuckAfterSeconds: 260, waitReason: "HOLDING THE BEARING", tick },
  marker: (handles, candidate) => handles.target(candidate.id === 'station:transit:reboard' ? 'fabricator' : 'station'),
  journey: [
  {
    "id": "objective:ch10:ch10-transit",
    "beat": "ch10-transit",
    "criticality": "mandatory",
    "interaction": {
      "intent": "Launch on the claimed bearing and hold course until the source resolves at standoff; after the threshold hand-back, close the final corridor and request docking clearance if desired.",
      "completionEvidenceRefs": [
        "milestone:story:ch10-transit-ignited",
        "milestone:story:ch10-seam-passed",
        "milestone:story:ch10-station-resolved"
      ],
      "forbiddenInteractionIds": [],
      "feedbackWithinMs": 1000
    },
    "postconditions": {
      "clearPromptWithinFrames": 2,
      "clearMarkerWithinFrames": 2,
      "mustNotReappearWithoutStateChange": true
    },
    "placementFitness": {
      "whyNow": "The bearing was issued but the going is the player's, so the last act of the chapter is a flight nobody ordered.",
      "capability": "ch8 launch and cruise grammar aimed at a non-planet target for the first time in the story.",
      "storyFunction": "Scale and smallness, then threshold restraint: the station resolves before the hand-back opens the already-earned bearing into a real place the player may enter.",
      "expectedPlayerSeconds": {
        "min": 120,
        "max": 600
      },
      "spatialTolerance": "Travel objectives do not fail if course drifts; the seam latch fires once from either its view-cone or its look-independent range condition.",
      "recovery": "Shipped ch8 flight rescue applies unchanged; a rescue never claims or docks on the player's behalf. After the hand-back, normal approach alignment, range, and speed gates remain player-owned.",
      "blocking": true,
      "reviewOwners": [
        "story",
        "score",
        "cinematography",
        "ux"
      ]
    }
  }
]
});
import type { RailRuntime } from '../../autopilot.ts';

/** ch10-transit: player inputs and registered world transactions only. */
export function tick(ctx: RailRuntime): void {
{
    // Same clean slate as the ask beat, and for the same reason: the transit
    // inherits whatever the ask left asserted, and a stale interact here
    // would ask to land on the way to a station that offers no berth.
    ctx.clearControls();
    const flight = ctx.getSpaceFlightSnapshot();
    // THE BEAT DOES NOT ALWAYS BEGIN IN THE COCKPIT. Played through, chapter
    // 10 enters the transit ON FOOT at the wreck relay — she has just claimed
    // the bearing standing beside it — so a rail that only knows how to fly
    // stands at the relay forever. The deep link seeds the pilot already in
    // flight, which is exactly why the deep-link tail passed while the flow
    // path never ignited. Same boarding grammar the ask beat uses.
    if (flight.controlMode !== 'flight') {
        const parked = ctx.getShipPosition();
        if (!parked)
            return;
        const hatch = ctx._goalScratch.set(parked[0], parked[1], parked[2]);
        ctx.walkToward(hatch, 2.4, 1.1);
        if (ctx.getPlayerWorldPosition().distanceTo(hatch) <= 3.5)
            ctx.enterShip();
        return;
    }
    // Ignite, then hold the claimed bearing. Nothing else: the seam, the
    // resolve and the hand-back are all facts of the flight, not acts.
    //
    // THE END OF THE LEG IS A STANDOFF, NOT A DOCK. arrivalStandoff(body,
    // 1,500) sits outside CORRIDOR_RANGE 1,400 precisely so no corridor is
    // published and no berth is offered, so the pilot cuts thrust there and
    // holds. Flying on would enter the corridor and stage a shot of an
    // invitation the chapter refuses to make.
    const contact = ctx.spaceStationApproachGeometry();
    const atStandoff = contact !== null
        && contact.readout.distance <= ctx.STATION_STANDOFF_DISTANCE;
    ctx.controls.jump = flight.controlMode === 'flight' && flight.phase === 'surface';
    ctx.controls.forward = flight.controlMode === 'flight'
        && flight.phase !== 'surface'
        && !atStandoff;
    // NO SPRINT, AND THIS IS A LENS DECISION, NOT A SPEED ONE.
    //
    // The ch8 legs above copy `sprint = forward`, and inheriting that here
    // staged an undeclared lens move through the chapter's own hero frames:
    // resolveShipBoost() is `forwardHeld && sprintHeld`, boost drives
    // shipFlightFeedback's fovTarget = 70 + 9 x boost, and ShipController
    // writes that straight onto the render camera. So the rail cruised at FOV
    // 79 and settled back to 70 only when `atStandoff` dropped forward —
    // which is exactly the 79-at-the-seam / 70.0002-at-the-cut-line split the
    // cinematography pass measured, and the contract declares FOV 70
    // throughout the transit. It was never the player's boost and never
    // shipped feel arriving on its own: this rail asked for it.
    //
    // Suppressing it also removes the cockpit-recede artifact at the root.
    // The shell's FOV compensation is exact and unclamped
    // (tan(39.5)/tan(35) = 1.17727 at 79, 1.03761 at 72, 1.00000 at 70), so
    // the silhouette was never wrong — but at scale >= 1.0708 (FOV 73.72) the
    // outer shell walls pass outside the cabin lamp's 6.5-unit reach and fall
    // to their emissive floor, which against black space reads as the seat
    // having pulled back. At FOV 70 the walls sit 6.09 units out and stay lit.
    //
    // The cost is honest and is travel time only: every trigger on this leg
    // is distance- or state-keyed, not clocked, so the seam range, the
    // standoff and the hand-back are unmoved. Terminal speed drops from the
    // clamped 320 u/s to 117.5 (accel 60 against the 0.6/s damping), which
    // lengthens the cruise rather than changing anything it arrives at.
    ctx.controls.sprint = false;
    return;
}
}

