    screeningClock = 0;
    railStuckEvents.length = 0;
    railBackstops.length = 0;
    lastScreeningActionAt = -10;
    dryCrossFaceWaterContactFramesTotal = 0;
    dryWalkWaterContactFramesTotal = 0;
  }
