    const desired = new THREE.Quaternion().setFromRotationMatrix(
      new THREE.Matrix4().lookAt(new THREE.Vector3(), desiredDirection, referenceUp)
    );
    quat.slerp(desired, 1 - Math.exp(-2.4 * dt));
  }
}

