export function routeProgressUnits(
  route: readonly CommonGroundPoint[],
  body: CommonGroundPoint,
  previousUnits: number,
  corridorRadius = 2.5,
  maxAdvanceUnits = 3
): number {
  let travelled = 0;
  let best = previousUnits;
  for (let index = 1; index < route.length; index += 1) {
    const from = route[index - 1];
    const to = route[index];
    const segment = distanceBetween(from, to);
    if (segment <= 0) continue;
    const dx = to.x - from.x;
    const dy = to.y - from.y;
    const dz = to.z - from.z;
    const t = Math.max(0, Math.min(1,
      ((body.x - from.x) * dx + (body.y - from.y) * dy + (body.z - from.z) * dz)
        / (segment * segment)));
    const closest = { x: from.x + dx * t, y: from.y + dy * t, z: from.z + dz * t };
    const arc = travelled + segment * t;
    // THE FRONTIER IS CONTIGUOUS. Standing at the far end of the span is not
    // eighteen units of passage: a body may only claim arc length it has
    // actually reached, so an advance is refused unless it is adjacent to the
    // progress already earned. This is what stops an endpoint shortcut, old
    // footsteps and a teleport from reading as a walked comparison.
    if (distanceBetween(body, closest) <= corridorRadius && arc <= best + maxAdvanceUnits) {
      best = Math.max(best, arc);
    }
    travelled += segment;
  }
  return Math.max(previousUnits, Math.min(best, travelled));
}

