import type { RailRuntime } from '../autopilot.ts';

/**
 * The one ch13 rail body. Move, look, act — nothing else.
 *
 * All four ch13 rails share it because they do the same thing: they read the
 * plan the DIRECTOR already published for the player, and they press it. The
 * plan can only ever name an interaction the live resolver is currently
 * offering, so a screening cannot reach a verb a player could not. Nothing here
 * grants an item, marks a milestone or advances a beat; when the plan says
 * `hold`, the rail holds and the shipped stuck reporting does the rest.
 */
export function tickCommonGroundRail(ctx: RailRuntime): void {
  ctx.clearControls();
  const plan = ctx.commonGroundRailPlan();
  const flight = ctx.getSpaceFlightSnapshot();
  switch (plan.action) {
    case 'walk': {
      if (!plan.target) return;
      const goal = ctx._goalScratch.set(plan.target[0], plan.target[1], plan.target[2]);
      ctx.walkToward(goal, 1.2, 0.8);
      return;
    }
    case 'interact': {
      if (!plan.target || !plan.interactionId) return;
      const goal = ctx._goalScratch.set(plan.target[0], plan.target[1], plan.target[2]);
      // Close the last of the distance with the same walk the player uses, then
      // perform the interaction the resolver is offering right now.
      if (ctx.walkToward(goal, 1.2, 0.8) <= 4.2 && ctx.screeningActionReady()) {
        ctx.noteScreeningAction();
        ctx.performStoryInteraction(plan.interactionId as never);
      }
      return;
    }
